class Command(BaseCommand):
    help = 'Seed the database with ML learning content'

    def handle(self, *args, **options):
        self.stdout.write('Seeding ML Libraries...')
        self.seed_libraries()

        self.stdout.write('Seeding Chart Templates...')
        self.seed_charts()

        self.stdout.write('Seeding Pandas/NumPy Functions...')
        self.seed_functions()

        self.stdout.write('Seeding ML Models...')
        self.seed_models()

        self.stdout.write('Seeding Test Templates & Metrics...')
        self.seed_testing()

        self.stdout.write(self.style.SUCCESS('All data seeded successfully!'))

